/**
 * SEO articles. Generated by the SEO engine (claude-seo-engine, live path
 * core/pipeline.mjs::writeOneArticle via scripts/gt-test-sample-write.mjs) into
 * clients/buildingsforlifeltd.com/<run>/, then imported by
 * scripts/import-articles.mjs -> articles.json. Bodies are the engine's HTML,
 * rendered as-is (article links are the engine's business, ANCHOR-LAW 6).
 * Nothing here is hand-written.
 */
import data from './articles.json';

export interface Article {
  slug: string; // engine URL contract: /<service>-<town>/
  title: string; // engine pageTitle (H1)
  metaTitle: string; // engine seoTitle
  description: string; // engine metaDescription
  topic: string; // service name
  summary: string; // engine hero lead
  hero: string;
  heroAlt: string;
  related: string; // service hub slug
  town: string;
  bodyHtml: string; // engine introHtml + bodyHtml (takeaways, CTA blocks, FAQ included)
  faqs: { q: string; a: string }[]; // read back from the engine's FAQPage JSON-LD
  words: number | null;
  engine: { runId: string; rank: number; publishDate?: string; persona?: string; gates?: string; url?: string };
}

export const articles: Article[] = data as Article[];
